function bapakFocus(q){
 const text=String(q?.[2]||"").toLowerCase(),prior=BAPAK_PRIOR[String(q?.[1]||"")]||{};
 const ranked=BAPAK_FILTERS.map((f,idx)=>{
  let score=Number(prior[f.id]||0);
  for(const term of f.terms)if(text.includes(term))score++;
  return {...f,score,idx};
 }).sort((a,b)=>b.score-a.score||a.idx-b.idx);
 const first=ranked[0],second=ranked[1],takeSecond=second.score>=Math.max(2,first.score-2);
 return takeSecond?[first,second]:[first];
}
